using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements using SIMD vectorization.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<float>.Count)
        {
            var vProduct = Vector<float>.One;
            var asVectors = MemoryMarshal.Cast<float, Vector<float>>(values);

            // Process two vectors per iteration to exploit ILP
            int limit = asVectors.Length & ~1;
            var vProduct2 = Vector<float>.One;
            int vi = 0;
            for (; vi < limit; vi += 2)
            {
                vProduct *= asVectors[vi];
                vProduct2 *= asVectors[vi + 1];
            }
            if (vi < asVectors.Length)
            {
                vProduct *= asVectors[vi];
            }

            vProduct *= vProduct2;

            // Horizontal reduction of all SIMD lanes
            float product = vProduct[0];
            for (int lane = 1; lane < Vector<float>.Count; lane++)
                product *= vProduct[lane];

            // Scalar tail for remaining elements
            i = asVectors.Length * Vector<float>.Count;
            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        // Scalar fallback with 4x unroll for ILP
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int scalarLimit = values.Length - 3;
        for (; i < scalarLimit; i += 4)
        {
            p0 *= values[i];
            p1 *= values[i + 1];
            p2 *= values[i + 2];
            p3 *= values[i + 3];
        }
        for (; i < values.Length; i++)
            p0 *= values[i];

        return p0 * p1 * p2 * p3;
    }
}

